insert into public.library_records (library_key, code, name, data, status, effective_from, notes) values
('ig_subscores','DURABILITY','Durability','{"seq":1,"category":"Circular design","espr_aligned":true,"description":"Long-lasting displays, shelving, and furniture designed for repeated use or redeployment.","data_inputs":["Life expectancy - in days"],"rule":"Life expectancy (activation period) mapped to an impact level: longer is better.","weight_standard":10,"weight_promo":20,"status":"live","workbook_notes":"Benchmark: set a category-specific target (e.g., 5 campaigns or 10 years). Use chat gpt to define 1 benchmark for each product type? Document it - In days is nice to have but I am worried about data quality. Start with Default per product type - Put in days or months. Informative bullet otherwise documentation (adm def). Later stage capture the real campaign number of day expected - at the right time (Brief?)"}'::jsonb,'active','2026-01-01',null),
('ig_subscores','REUSABILITY','Reusability','{"seq":2,"category":"Circular design","espr_aligned":true,"description":"Modular display systems that can be refreshed seasonally without full replacement.","data_inputs":["Designed for reuse and second life utilisation"],"rule":"Designed for reuse and second-life use: yes 100, no 0.","weight_standard":10,"status":"live","workbook_notes":"Clear definition needed. Use ESPR definition add in the definition the updatable graphics and digital content"}'::jsonb,'active','2026-01-01',null),
('ig_subscores','REPAIRABILITY','Repairability','{"seq":3,"category":"Circular design","espr_aligned":true,"description":"Replaceable components","data_inputs":["Design to be modular"],"rule":"Designed to be modular (replaceable components): yes 100, no 0.","weight_standard":10,"status":"live","workbook_notes":"This will highly be a 0 for 2D and Promo. + Maybe we should think about how to capture repairability outside modularity. Exclude for Promo and put 15/15 to get a 30?"}'::jsonb,'active','2026-01-01',null),
('ig_subscores','RECYCLABILITY','Recyclability','{"seq":4,"category":"Circular design","espr_aligned":true,"description":"Mono-material structures and easily separable components for end-of-life","data_inputs":["Designed lamination, edging and foil free","Designed for ease of material separation","Mono Material vs Multi Material","Recyclable %"],"rule":"Recyclable % of the weight. Not recyclable when there is any finishing or decoration, or when multi-material parts do not separate easily.","weight_standard":5,"weight_promo":15,"status":"live","workbook_notes":"Current methodo except lamination for gdt to be included + based on specifications and not question."}'::jsonb,'active','2026-01-01',null),
('ig_subscores','RESOURCE_USE','Resource Use & Efficiency','{"seq":5,"category":"Resource use & efficiency","espr_aligned":true,"description":"Lightweight design, lower material intensity, minimal waste during manufacture","data_inputs":["Designed to optimal size and weight","Plastic free materials","Material certification"],"rule":"Average of: optimal size and weight (yes 100), plastic free (no plastic 100), certified material (certified 100).","weight_standard":5,"weight_promo":5,"status":"live","workbook_notes":"Benchmark per product type of optimal weight and volume? \r\ncarbon vs tonnes? Vs median average for the category. Intensity (maybe carbon + water)\r\nTake the highest one + high spend to be reengineered"}'::jsonb,'active','2026-01-01',null),
('ig_subscores','SUBSTANCES','Potential Substances of concern','{"seq":6,"category":"Resource use & efficiency","espr_aligned":true,"description":"ESPR idea is to reduce substances that may hinder circularity, e.g., hazardous, toxic, or contaminating substances that impede recycling, reuse, or safe handling. \r\nKeep but add \"Potential\".","data_inputs":["Harmful substrate (PVC, BPA, PU foam, etc)","Inks","Varnish","Electronics","Oekotek (for textile)"],"rule":"Average of the items that apply: harmful substrates (PVC, BPA, PU foam...), inks, varnish, electronics, OEKO-TEX for textiles.","weight_standard":5,"weight_promo":5,"status":"live"}'::jsonb,'active','2026-01-01',null),
('ig_subscores','RECYCLED_CONTENT','Recycled Content','{"seq":7,"category":"Resource use & efficiency","espr_aligned":true,"description":"Post-consumer recycled content","data_inputs":["Exact recycled content %"],"rule":"Exact post-consumer recycled content, weighted by mass.","weight_standard":5,"weight_promo":5,"status":"live","workbook_notes":"Assumptions aligned with PCR. Next step made mandatory + clear definition that it is post consumer"}'::jsonb,'active','2026-01-01',null),
('ig_subscores','PEF','Product Environmental Footprint','{"seq":8,"category":"Environmental footprint","espr_aligned":true,"description":"Measured reduction in material and transport impacts.","data_inputs":["See PEF Scoring tab"],"rule":"PEF score scaled 0-100 against the reference: 100 × (1 − PEF mPt ÷ reference), floored at 0. Reference = 95th percentile of our PEF results.","weight_standard":50,"weight_promo":50,"status":"live","workbook_notes":"As the score is dimensionless, if we want to convert into a range between 0 to 100 we will need to compare"}'::jsonb,'active','2026-01-01',null),
('ig_subscores','SUPPLIER','Supplier Score','{"seq":9,"category":"Supplier score","espr_aligned":false,"data_inputs":["Work in Progress (Guy and Olivia)"],"rule":"Work in progress: supplier sustainability scoring (CSR, EMS, FSC, Sedex, diverse supplier, renewable energy). Weight 0 until agreed.","weight_standard":0,"weight_promo":0,"status":"work_in_progress"}'::jsonb,'active','2026-01-01',null),
('ig_subscores','LOGISTICS','Logistics','{"seq":10,"category":"Logistics","espr_aligned":false,"data_inputs":["Flat packed, local, no plastic?"],"rule":"Work in progress: flat packed, local, no plastic. Weight 0 until agreed.","weight_standard":0,"weight_promo":0,"status":"work_in_progress"}'::jsonb,'active','2026-01-01',null);
