insert into public.library_records (library_key, code, name, data, status, effective_from, notes) values
('ig_open_items','IG-01','PEF to 0-100 scaling','{"seq":1,"status":"decided","why":"Workbook listed four options for the maximum. Decided 5 Nov 2026: 95th percentile of our own PEF results.","next_step":"Recalculate the reference as PEF results build up; seeded from 6 worked examples only."}'::jsonb,'active','2026-01-01',null),
('ig_open_items','IG-02','Durability mapping tops out at 80','{"seq":2,"status":"open","why":"Activation periods are mapped to impact levels 5 (1 day) to 1 (more than 2 years); level 1 scores 80, so no item reaches 100.","next_step":"Confirm whether more than 2 years should score 100, or add a level-0 band."}'::jsonb,'active','2026-01-01',null),
('ig_open_items','IG-03','How items combine inside a sub-score','{"seq":3,"status":"open","why":"Resource use (3 items) and substances of concern (up to 5 items) have one weight each; the workbook does not say how the items combine.","next_step":"System Guy averages the items that apply. Confirm or set item weights."}'::jsonb,'active','2026-01-01',null),
